80	/**
81	 * DashboardLayout — wrapper público. MiaProvider foi MOVIDO pro App.tsx
82	 * (acima de Routes) pra persistir state entre navegações — antes ele
83	 * re-montava em cada route change, fazendo chat sumir + tab resetar
84	 * quando MIA usava do_navigate.
85	 */
86	export function DashboardLayout({ children }: DashboardLayoutProps) {
87	  return <DashboardLayoutInner>{children}</DashboardLayoutInner>;
88	}
